def color_func(Y, mode='polygon', global_bounds=None):
    if mode == 'polygon':
        # 用細胞外觀的亮度表示 Cyclin 的濃度，當達到高點時代表準備分裂
        vmin, vmax = global_bounds[0] 
        norm = (Y[:,0] - vmin) / (vmax - vmin + 1e-8)
        return plt.cm.YlOrRd(norm)
    elif mode == 'center':
        vmin, vmax = global_bounds[1] 
        norm = (Y[:,1] - vmin) / (vmax - vmin + 1e-8)
        return plt.cm.Greys(norm)
    elif mode == 'membrane':
        # 當 Cyclin 大於閾值，將細胞膜標記為紅色警告 (M-phase)
        color = np.zeros((Y.shape[0], 4))
        mask = Y[:,0] > 0.75
        color[mask] = [0, 1, 0, 1]   # 紅色
        color[~mask] = [0, 0, 0, 1]  # 黑色
        return color
    else:
        return None
